def _numeric_coerce(value) -> float:
    """Apply legacy numeric-context coercion."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Perform legacy CRMScript numeric division."""
    numerator = _numeric_coerce(a)
    divisor = _numeric_coerce(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    return numerator / divisor, []
